BEGIN;
CREATE TEMP TABLE expected_closure_coverage AS SELECT * FROM mapping.phase3_requirement_coverage WHERE false;
INSERT INTO expected_closure_coverage (coverage_id,requirement_id,coverage_state,semantic_review_outcome,justification,limitations,identified_paths,review_status,reviewed_by,reviewed_at,reviewed_against_baseline) VALUES ('M06-B02-COV-A05-P01-002','EU-2017-1926-REQ-A05-P01-002','PARTIAL','ACCEPTED_WITH_LIMITATIONS','Evaluated B02 scope: ROAD_STATUS_DISRUPTION only. Persisted C01 category-specific partial mappings support a bounded part of the road dynamic-data requirement. PARTIAL is a semantic review, not a ratio of mappings. DATEX II RTTI RRP 2022/670 evidence; individual releases remain unresolved.','Not exhaustive; not observed implementation; not legal compliance conclusion. 5-SN-D deferred: profile/identity ambiguity. Frozen 2015/962 literal reference preserved; 2022/670 succession context is not a legal substitution. Other dynamic road-data scope and exact releases not established.','MAPPING:M06-B02-MAP-A05-P01-002-DATEX-4-SN-A;MAPPING:M06-B02-MAP-A05-P01-002-DATEX-4-SN-B;MAPPING:M06-B02-MAP-A05-P01-002-DATEX-4-SN-C;MAPPING:M06-B02-MAP-A05-P01-002-DATEX-4-SN-D;MAPPING:M06-B02-MAP-A05-P01-002-DATEX-5-SN-A;MAPPING:M06-B02-MAP-A05-P01-002-DATEX-5-SN-B;MAPPING:M06-B02-MAP-A05-P01-002-DATEX-5-SN-C','REVIEWED','Yeison Arbey Carrillo Lemus','2026-09-28','M06_B02_FINAL_CLOSURE_2026-09-28; S1+B02A; PRE_DB_SHA256=657A48BF6472F958980646193F8CBAA81C01F316D2385D0F4E81F7EF13BAA791'),
('M06-B02-COV-A05-P02-001','EU-2017-1926-REQ-A05-P02-001','PARTIAL','ACCEPTED_WITH_LIMITATIONS','Evaluated B02 scope: conditional Annex 2.1/2.2 concepts, with support limited to PASSENGER_RT_STATUS_DISRUPTION through C07 ET/SX. SIRI 2.1 / EPIP-RT CEN/TS 15531-7:2025. The accepted partial mappings support PARTIAL semantic coverage without establishing all concepts; no count-based percentage.','Not exhaustive; not observed implementation; not legal compliance conclusion. Gaps: C04 Article 5(2) road applicability; C08 normative FM/facility element path; CM guaranteed-connections bridge; U01 PARKING_TARIFF minimum general profile/version/elements and applicability; U02 SHARED_VEHICLE_AVAILABILITY modal profile/element evidence; U03 PARKING_AVAILABILITY on/off-street minimum profile and crosswalk. All deferred for closure; exact profile constraints and representability not established.','MAPPING:M06-B02-MAP-A05-P02-001-SIRI-ET;MAPPING:M06-B02-MAP-A05-P02-001-SIRI-SX','REVIEWED','Yeison Arbey Carrillo Lemus','2026-09-28','M06_B02_FINAL_CLOSURE_2026-09-28; S1+B02A; PRE_DB_SHA256=657A48BF6472F958980646193F8CBAA81C01F316D2385D0F4E81F7EF13BAA791');
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM expected_closure_coverage e JOIN mapping.phase3_requirement_coverage t ON e.coverage_id=t.coverage_id OR e.requirement_id=t.requirement_id WHERE NOT (e.coverage_id IS NOT DISTINCT FROM t.coverage_id AND e.requirement_id IS NOT DISTINCT FROM t.requirement_id AND e.coverage_state IS NOT DISTINCT FROM t.coverage_state AND e.semantic_review_outcome IS NOT DISTINCT FROM t.semantic_review_outcome AND e.justification IS NOT DISTINCT FROM t.justification AND e.limitations IS NOT DISTINCT FROM t.limitations AND e.identified_paths IS NOT DISTINCT FROM t.identified_paths AND e.review_status IS NOT DISTINCT FROM t.review_status AND e.reviewed_by IS NOT DISTINCT FROM t.reviewed_by AND e.reviewed_at IS NOT DISTINCT FROM t.reviewed_at AND e.reviewed_against_baseline IS NOT DISTINCT FROM t.reviewed_against_baseline)) THEN 'COVERAGE_CONFLICT:PASS' ELSE error('COVERAGE_CONFLICT') END AS check_result;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM expected_closure_coverage e LEFT JOIN compliance.requirements r USING(requirement_id) WHERE r.requirement_id IS NULL) THEN 'COVERAGE_REQUIREMENT:PASS' ELSE error('COVERAGE_REQUIREMENT') END AS check_result;
