INSERT INTO mapping.phase3_requirement_coverage SELECT e.* FROM expected_closure_coverage e WHERE NOT EXISTS(SELECT 1 FROM mapping.phase3_requirement_coverage t WHERE e.coverage_id IS NOT DISTINCT FROM t.coverage_id);
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM expected_closure_coverage e JOIN mapping.phase3_requirement_coverage t ON e.coverage_id=t.coverage_id OR e.requirement_id=t.requirement_id WHERE NOT (e.coverage_id IS NOT DISTINCT FROM t.coverage_id AND e.requirement_id IS NOT DISTINCT FROM t.requirement_id AND e.coverage_state IS NOT DISTINCT FROM t.coverage_state AND e.semantic_review_outcome IS NOT DISTINCT FROM t.semantic_review_outcome AND e.justification IS NOT DISTINCT FROM t.justification AND e.limitations IS NOT DISTINCT FROM t.limitations AND e.identified_paths IS NOT DISTINCT FROM t.identified_paths AND e.review_status IS NOT DISTINCT FROM t.review_status AND e.reviewed_by IS NOT DISTINCT FROM t.reviewed_by AND e.reviewed_at IS NOT DISTINCT FROM t.reviewed_at AND e.reviewed_against_baseline IS NOT DISTINCT FROM t.reviewed_against_baseline)) THEN 'COVERAGE_CONFLICT:PASS' ELSE error('COVERAGE_CONFLICT') END AS check_result;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM expected_closure_coverage e LEFT JOIN compliance.requirements r USING(requirement_id) WHERE r.requirement_id IS NULL) THEN 'COVERAGE_REQUIREMENT:PASS' ELSE error('COVERAGE_REQUIREMENT') END AS check_result;
SELECT CASE WHEN NOT EXISTS((SELECT * FROM audit.evidence EXCEPT ALL (SELECT * FROM before_0)) UNION ALL ((SELECT * FROM before_0) EXCEPT ALL SELECT * FROM audit.evidence)) THEN 'EXACT_DELTA_0:PASS' ELSE error('EXACT_DELTA_0') END AS check_result;
