SELECT CASE WHEN NOT EXISTS((SELECT * FROM audit.rules EXCEPT ALL (SELECT * FROM before_2)) UNION ALL ((SELECT * FROM before_2) EXCEPT ALL SELECT * FROM audit.rules)) THEN 'EXACT_DELTA_2:PASS' ELSE error('EXACT_DELTA_2') END AS check_result;
