SELECT CASE WHEN NOT EXISTS((SELECT * FROM compliance.requirement_candidate_sources EXCEPT ALL (SELECT * FROM before_7)) UNION ALL ((SELECT * FROM before_7) EXCEPT ALL SELECT * FROM compliance.requirement_candidate_sources)) THEN 'EXACT_DELTA_7:PASS' ELSE error('EXACT_DELTA_7') END AS check_result;
SELECT CASE WHEN NOT EXISTS((SELECT * FROM compliance.requirement_candidates EXCEPT ALL (SELECT * FROM before_8)) UNION ALL ((SELECT * FROM before_8) EXCEPT ALL SELECT * FROM compliance.requirement_candidates)) THEN 'EXACT_DELTA_8:PASS' ELSE error('EXACT_DELTA_8') END AS check_result;
SELECT CASE WHEN NOT EXISTS((SELECT * FROM compliance.requirements EXCEPT ALL (SELECT * FROM before_9)) UNION ALL ((SELECT * FROM before_9) EXCEPT ALL SELECT * FROM compliance.requirements)) THEN 'EXACT_DELTA_9:PASS' ELSE error('EXACT_DELTA_9') END AS check_result;
