SELECT CASE WHEN NOT EXISTS((SELECT * FROM mapping.phase3_capabilities EXCEPT ALL (SELECT * FROM before_14)) UNION ALL ((SELECT * FROM before_14) EXCEPT ALL SELECT * FROM mapping.phase3_capabilities)) THEN 'EXACT_DELTA_14:PASS' ELSE error('EXACT_DELTA_14') END AS check_result;
