SELECT CASE WHEN NOT EXISTS((SELECT * FROM mapping.phase3_mapping_scope_units EXCEPT ALL (SELECT * FROM before_19)) UNION ALL ((SELECT * FROM before_19) EXCEPT ALL SELECT * FROM mapping.phase3_mapping_scope_units)) THEN 'EXACT_DELTA_19:PASS' ELSE error('EXACT_DELTA_19') END AS check_result;
SELECT CASE WHEN NOT EXISTS((SELECT * FROM mapping.phase3_observed_evidence EXCEPT ALL (SELECT * FROM before_20)) UNION ALL ((SELECT * FROM before_20) EXCEPT ALL SELECT * FROM mapping.phase3_observed_evidence)) THEN 'EXACT_DELTA_20:PASS' ELSE error('EXACT_DELTA_20') END AS check_result;
