SELECT CASE WHEN NOT EXISTS((SELECT * FROM mapping.phase3_requirement_concepts EXCEPT ALL (SELECT * FROM before_23)) UNION ALL ((SELECT * FROM before_23) EXCEPT ALL SELECT * FROM mapping.phase3_requirement_concepts)) THEN 'EXACT_DELTA_23:PASS' ELSE error('EXACT_DELTA_23') END AS check_result;
SELECT CASE WHEN NOT EXISTS((SELECT * FROM mapping.phase3_requirement_coverage EXCEPT ALL (SELECT * FROM before_24 UNION ALL SELECT e.* FROM expected_closure_coverage e WHERE NOT EXISTS(SELECT 1 FROM before_24 t WHERE e.coverage_id IS NOT DISTINCT FROM t.coverage_id))) UNION ALL ((SELECT * FROM before_24 UNION ALL SELECT e.* FROM expected_closure_coverage e WHERE NOT EXISTS(SELECT 1 FROM before_24 t WHERE e.coverage_id IS NOT DISTINCT FROM t.coverage_id)) EXCEPT ALL SELECT * FROM mapping.phase3_requirement_coverage)) THEN 'EXACT_DELTA_24:PASS' ELSE error('EXACT_DELTA_24') END AS check_result;
SELECT CASE WHEN NOT EXISTS((SELECT * FROM mapping.phase3_requirement_families EXCEPT ALL (SELECT * FROM before_25)) UNION ALL ((SELECT * FROM before_25) EXCEPT ALL SELECT * FROM mapping.phase3_requirement_families)) THEN 'EXACT_DELTA_25:PASS' ELSE error('EXACT_DELTA_25') END AS check_result;
